const countBillingUsageInPeriodForOrg = `-- name: CountBillingUsageInPeriodForOrg :one
SELECT
    (SELECT COUNT(*) FROM documents d
      WHERE d.org_id = $1
        AND d.created_at >= $2
        AND d.created_at < $3
        AND NOT EXISTS (
            SELECT 1
            FROM compliance_baselines cb
            WHERE cb.org_id = d.org_id
              AND (cb.records_doc_id = d.id OR cb.privacy_notice_id = d.id)
        ))::BIGINT AS documents_used,
    (SELECT COUNT(*) FROM recipients r
      JOIN documents d ON d.id = r.document_id
      WHERE d.org_id = $1
        AND r.created_at >= $2
        AND r.created_at < $3
        AND NOT EXISTS (
            SELECT 1
            FROM compliance_baselines cb
            WHERE cb.org_id = d.org_id
              AND (cb.records_doc_id = d.id OR cb.privacy_notice_id = d.id)
        ))::BIGINT AS recipients_used
`

