const listSubscriptionsOverQuotaWarning = `-- name: ListSubscriptionsOverQuotaWarning :many
WITH usage AS (
    SELECT
        os.id AS subscription_id,
        os.org_id,
        os.current_period_start,
        os.current_period_end,
        bp.slug AS plan_slug,
        bp.name AS plan_name,
        bp.document_quota_monthly,
        bp.recipient_quota_monthly,
        (SELECT COUNT(*) FROM documents d
            WHERE d.org_id = os.org_id
              AND d.created_at >= os.current_period_start
              AND d.created_at < COALESCE(os.current_period_end, now())
              AND NOT EXISTS (
                  SELECT 1
                  FROM compliance_baselines cb
                  WHERE cb.org_id = d.org_id
                    AND (cb.records_doc_id = d.id OR cb.privacy_notice_id = d.id)
              ))::INT AS documents_used,
        (SELECT COUNT(*) FROM recipients r
            JOIN documents d2 ON d2.id = r.document_id
            WHERE d2.org_id = os.org_id
              AND r.created_at >= os.current_period_start
              AND r.created_at < COALESCE(os.current_period_end, now())
              AND NOT EXISTS (
                  SELECT 1
                  FROM compliance_baselines cb
                  WHERE cb.org_id = d2.org_id
                    AND (cb.records_doc_id = d2.id OR cb.privacy_notice_id = d2.id)
              ))::INT AS recipients_used,
        os.last_quota_warning_sent_at
    FROM org_subscriptions os
    JOIN billing_plans bp ON bp.id = os.plan_id
    WHERE os.status IN ('trialing', 'active')
      AND os.current_period_start IS NOT NULL
)
SELECT
    subscription_id,
    org_id,
    current_period_start,
    current_period_end,
    plan_slug,
    plan_name,
    document_quota_monthly,
    recipient_quota_monthly,
    documents_used,
    recipients_used
FROM usage
WHERE (last_quota_warning_sent_at IS NULL
       OR last_quota_warning_sent_at < current_period_start)
  AND (
        (document_quota_monthly > 0 AND documents_used * 100 >= document_quota_monthly * $1::INT)
     OR (recipient_quota_monthly > 0 AND recipients_used * 100 >= recipient_quota_monthly * $1::INT)
  )
`

type ListSubscriptionsOverQuotaWarningRow struct {
	SubscriptionID        uuid.UUID          `json:"subscription_id"`
	OrgID                 uuid.UUID          `json:"org_id"`
	CurrentPeriodStart    pgtype.Timestamptz `json:"current_period_start"`
	CurrentPeriodEnd      pgtype.Timestamptz `json:"current_period_end"`
	PlanSlug              string             `json:"plan_slug"`
	PlanName              string             `json:"plan_name"`
	DocumentQuotaMonthly  int32              `json:"document_quota_monthly"`
	RecipientQuotaMonthly int32              `json:"recipient_quota_monthly"`
	DocumentsUsed         int32              `json:"documents_used"`
	RecipientsUsed        int32              `json:"recipients_used"`
}

func (q *Queries) ListSubscriptionsOverQuotaWarning(ctx context.Context, dollar_1 int32) ([]*ListSubscriptionsOverQuotaWarningRow, error) {
	rows, err := q.db.Query(ctx, listSubscriptionsOverQuotaWarning, dollar_1)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []*ListSubscriptionsOverQuotaWarningRow{}
	for rows.Next() {
		var i ListSubscriptionsOverQuotaWarningRow
		if err := rows.Scan(
			&i.SubscriptionID,
			&i.OrgID,
			&i.CurrentPeriodStart,
			&i.CurrentPeriodEnd,
			&i.PlanSlug,
			&i.PlanName,
			&i.DocumentQuotaMonthly,
			&i.RecipientQuotaMonthly,
			&i.DocumentsUsed,
			&i.RecipientsUsed,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockBillingUsageForOrg = `-- name: LockBillingUsageForOrg :exec
SELECT pg_advisory_xact_lock(hashtextextended($1::text, 63001))
`

// Every quota-consuming authoring transaction uses the same lock key as the
// automation API. Collisions only serialize unrelated orgs; authorization and
// usage queries remain independently org-scoped.
func (q *Queries) LockBillingUsageForOrg(ctx context.Context, orgID string) error {
	_, err := q.db.Exec(ctx, lockBillingUsageForOrg, orgID)
	return err
}

